\title{Nilpotency of Additive Cellular Automata on Cyclic Lattices:\\
A Bridge Between Wolfram Dynamics and the Geometry of Roots of Unity}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We study the additive elementary cellular automaton on a finite cyclic lattice
$\ZZ/n$ whose local rule replaces each cell by the sum, modulo two, of itself and
its right neighbour. Encoding spatially $n$-periodic binary configurations as
elements of the finite ring $\Rn = \FF_2[X]/(X^n-1)$, we identify one time step
with multiplication by the distinguished element $u = 1+X$. We prove a sharp
dichotomy: the automaton is \emph{globally nilpotent}---every configuration
reaches the all-zero state in finitely many steps---if and only if $n$ is a power
of two. Algebraically, $u$ is nilpotent in $\Rn$ iff $n = 2^k$; geometrically,
the finite group scheme $\mu_n = \Spec \FF_2[X]/(X^n-1)$ is a non-reduced
(purely infinitesimal) ``fat point'' iff $n$ is a power of the characteristic.
When mortality holds, the nilpotency index---the exact relaxation time---equals
$n$. The proof combines the Frobenius ``freshman's dream,'' primality of $X+1$ in
$\FF_2[X]$, a derivative/parity argument, and a characteristic-two square-root
descent.
\end{abstract}

\maketitle

\section{Introduction}

Elementary cellular automata (ECAs) are the $256$ one-dimensional binary automata
whose next-cell value is a Boolean function of a three-cell neighbourhood. Among
them a distinguished subfamily is \emph{additive} (or \emph{linear}): those whose
local map is $\FF_2$-linear (Rules $60, 90, 102, 150, \dots$). For these the
global map is a linear operator, and the theory of the automaton becomes the
theory of a single element in a group ring.

We focus on the simplest nontrivial additive ECA on a finite \emph{cyclic}
lattice: the rule
\[
  s_i \longmapsto s_i + s_{i+1} \pmod 2, \qquad i \in \ZZ/n,
\]
(Wolfram's Rule~60) acting on spatially $n$-periodic configurations. Our central
question is one of \emph{global nilpotency}: for which lattice sizes $n$ does
every configuration eventually reach the quiescent all-zero state?

\begin{theorem}[Main Theorem]\label{thm:main}
For $n > 0$, the following are equivalent:
\begin{enumerate}
  \item every configuration $s \in \Rn$ satisfies
        $(\mathrm{caStep})^{[t]}(s) = 0$ for some $t$;
  \item $u = 1+X$ is nilpotent in $\Rn = \FF_2[X]/(X^n-1)$;
  \item $X^n - 1 = (X+1)^n$ in $\FF_2[X]$;
  \item the scheme $\mu_n$ over $\FF_2$ is non-reduced (a fat point);
  \item $n$ is a power of two.
\end{enumerate}
\end{theorem}

\section{The algebraic dictionary}

\begin{definition}[State ring]
The state ring of the automaton on $\ZZ/n$ is the finite quotient ring
$\Rn = \FF_2[X]/(X^n-1)$, with the $\FF_2$-linear isomorphism
$\Rn \cong \FF_2[\ZZ/n]$ sending the cell at position $i$ to the monomial $X^i$.
The configuration $(s_0,\dots,s_{n-1})$ corresponds to the residue class of
$\sum_{i=0}^{n-1} s_i X^i$.
\end{definition}

Multiplication by $X$ in $\Rn$ is the cyclic shift, since $X^n = 1$ closes the
lattice into a ring.

\begin{definition}[CA operator]
Let $u = 1+X \in \Rn$. One time step of the automaton is
$\mathrm{caStep}: \Rn \to \Rn$, $s \mapsto u\cdot s$. Indeed
$(1+X)\sum_i s_i X^i = \sum_i (s_i + s_{i-1})X^i$.
\end{definition}

\begin{lemma}[Time evolution]\label{lem:evol}
For all $t \in \NN$ and $s \in \Rn$, $(\mathrm{caStep})^{[t]}(s) = u^t \cdot s$.
\end{lemma}
\begin{proof}
Induction on $t$: $u^0 s = s$, and $u^{t+1}s = u(u^t s)$ by associativity.
\end{proof}

\begin{corollary}[Dynamics $\leftrightarrow$ nilpotency]\label{cor:dyn}
The automaton is globally nilpotent if and only if $u$ is a nilpotent element of
$\Rn$.
\end{corollary}
\begin{proof}
If $u^N = 0$ then $u^N s = 0$ for all $s$. Conversely, apply global nilpotency to
$s = 1$: some $t$ gives $u^t = 0$.
\end{proof}

\begin{lemma}[Nilpotency is divisibility]\label{lem:divis}
For $n > 0$, $u = 1+X$ is nilpotent in $\Rn$ iff $(X^n-1) \mid (X+1)^N$ in
$\FF_2[X]$ for some $N$.
\end{lemma}
\begin{proof}
$u^N = 0$ in $\Rn = \FF_2[X]/(X^n-1)$ means $(X+1)^N$ lies in the ideal
$(X^n-1)$, i.e. is divisible by $X^n-1$.
\end{proof}

\section{The characteristic-two toolbox}

All computations take place in $\FF_2[X]$, an integral domain of characteristic
two.

\begin{lemma}[Squaring is injective]\label{lem:sqinj}
For $A,B \in \FF_2[X]$, if $A^2 = B^2$ then $A = B$.
\end{lemma}
\begin{proof}
$(A+B)^2 = A^2 + B^2$ in characteristic two. If $A^2 = B^2$ then $(A+B)^2 = 0$,
so $A+B = 0$ (a domain has no nonzero nilpotents), whence $A = -B = B$.
\end{proof}

\begin{lemma}[Frequency doubling]\label{lem:freq}
For every $m$, $(X^m-1)^2 = X^{2m}-1$ in $\FF_2[X]$.
\end{lemma}
\begin{proof}
$X^m - 1 = X^m + 1$; by $(a+b)^2 = a^2 + b^2$,
$(X^m+1)^2 = X^{2m}+1 = X^{2m}-1$.
\end{proof}

\begin{lemma}[Primality of $X+1$]\label{lem:prime}
$X+1$ is prime in $\FF_2[X]$.
\end{lemma}
\begin{proof}
$X - c$ is prime over any field; take $c=1$ and use $-1 = 1$.
\end{proof}

\begin{lemma}[Frobenius collapse]\label{lem:frob}
For every $k$, $(X+1)^{2^k} = X^{2^k}+1 = X^{2^k}-1$ in $\FF_2[X]$.
\end{lemma}
\begin{proof}
The Frobenius endomorphism $a \mapsto a^2$ is a ring homomorphism in
characteristic two; iterating $k$ times, $a \mapsto a^{2^k}$ is too. Apply it to
$X+1$ and use $-1=1$.
\end{proof}

\section{The classification}

\begin{proposition}[Powers of two are mortal]\label{prop:pow2}
If $n = 2^k$ then $X^n-1 = (X+1)^n$; consequently $u^n = 0$ in $\Rn$ and the
automaton is globally nilpotent.
\end{proposition}
\begin{proof}
The identity is Lemma~\ref{lem:frob}. Reducing mod $X^n-1$, the residue of
$(X+1)^n = u^n$ is that of $X^n-1$, i.e. $0$; apply Corollary~\ref{cor:dyn}.
\end{proof}

\begin{proposition}[Even from the derivative]\label{prop:even}
If $n \ge 2$ and $X^n-1 = (X+1)^n$, then $n$ is even.
\end{proposition}
\begin{proof}
Differentiate: $nX^{n-1} = n(X+1)^{n-1}$. Evaluate at $X=0$. Since $n \ge 2$,
$X^{n-1}$ vanishes at $0$, so the left side is $0$; the right side is
$n\cdot 1^{n-1} = n$. Hence $n = 0$ in $\FF_2$.
\end{proof}

\begin{proposition}[Arithmetic heart]\label{prop:heart}
If $n > 0$ and $X^n-1 = (X+1)^n$, then $n = 2^k$ for some $k$.
\end{proposition}
\begin{proof}
Strong induction on $n$. If $n=1$, then $n = 2^0$. If $n \ge 2$, by
Proposition~\ref{prop:even} $n = 2m$ with $m \ge 1$. Then
\[
  (X^m-1)^2 = X^{2m}-1 = X^n-1 = (X+1)^n = (X+1)^{2m} = \big((X+1)^m\big)^2,
\]
using Lemma~\ref{lem:freq}. By Lemma~\ref{lem:sqinj},
$X^m-1 = (X+1)^m$. Since $m < n$, induction gives $m = 2^k$, so $n = 2^{k+1}$.
\end{proof}

\begin{proposition}[Prime-power divisors]\label{prop:ppdiv}
If $n > 0$ and $(X^n-1) \mid (X+1)^N$ for some $N$, then $X^n-1 = (X+1)^n$.
\end{proposition}
\begin{proof}
Since $X+1$ is prime (Lemma~\ref{lem:prime}), every divisor of $(X+1)^N$ is an
associate of some $(X+1)^i$. Both $X^n-1$ and $(X+1)^i$ are monic and monic
associates are equal, so $X^n-1 = (X+1)^i$. Comparing degrees, $i = n$.
\end{proof}

\begin{theorem}[Nilpotency dichotomy]\label{thm:nilp}
For $n > 0$, $u = 1+X$ is nilpotent in $\Rn$ iff $n = 2^k$ for some $k$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:divis}, nilpotency is equivalent to $(X^n-1)\mid(X+1)^N$ for
some $N$. ($\Rightarrow$) Propositions~\ref{prop:ppdiv} and \ref{prop:heart}.
($\Leftarrow$) Proposition~\ref{prop:pow2}.
\end{proof}

\begin{theorem}[Dynamical form]\label{thm:dyn}
For $n > 0$, every configuration on $\ZZ/n$ reaches the all-zero state in
finitely many steps iff $n$ is a power of two.
\end{theorem}
\begin{proof}
Combine Corollary~\ref{cor:dyn} with Theorem~\ref{thm:nilp}.
\end{proof}

\section{The relaxation time}

\begin{theorem}[Nilpotency index]\label{thm:index}
If $n = 2^k$, the nilpotency index of $u$---the least $N$ with $u^N = 0$ in
$\Rn$---is exactly $n$.
\end{theorem}
\begin{proof}
$u^n = (X+1)^n = X^n-1 \equiv 0$, so $N \le n$. If $u^N = 0$ with $N < n$, then
$(X^n-1)\mid(X+1)^N$; since $X^n-1 = (X+1)^n$, this forces
$(X+1)^n \mid (X+1)^N$, so $n \le N$, a contradiction. Hence $N = n$.
\end{proof}

The single-cell configuration on the $2^k$-lattice takes the full $n = 2^k$ steps
to die, and its space-time diagram is a wrapped Sierpi\'nski triangle (Pascal's
triangle modulo two).

\section{Geometric interpretation: fat points}

The ring $\Rn = \FF_2[X]/(X^n-1)$ is the coordinate ring of the finite group
scheme $\mu_n = \Spec \Rn$ of $n$-th roots of unity over $\FF_2$. The scheme is
reduced iff $\Rn$ has no nonzero nilpotents iff $X^n-1$ is squarefree iff $n$ is
odd. When $n = 2^k$, we have $X^n-1 = (X+1)^n$, a single prime to the $n$-th
power: $\mu_n$ is supported at the single point $X=1$ with multiplicity $n$---a
non-reduced \emph{fat point}, whose length equals the nilpotency index $n$.

\begin{center}
\begin{tabular}{@{}llll@{}}
\toprule
Dynamics & Algebra & Geometry & Arithmetic \\
\midrule
every pattern dies & $u=1+X$ nilpotent & $\mu_n$ a fat point & $n = 2^k$ \\
some pattern lives & $u$ not nilpotent & $\mu_n$ has reduced part & $n$ has odd factor $>1$ \\
relaxation time & nilpotency index of $u$ & length of fat point & $n = 2^k$ \\
\bottomrule
\end{tabular}
\end{center}

This specializes to $p=2$ the general principle that in characteristic $p$,
$\mu_n$ develops infinitesimal structure exactly when $p \mid n$, collapsing to a
fat point when $n$ is a power of $p$.

\section{Future directions}

\begin{enumerate}
  \item \textbf{Relaxation times for the mixed case} $n = 2^k m$ (odd $m > 1$),
        where the automaton is not nilpotent but the fat part still decays.
  \item \textbf{General additive rules}: replace $u = 1+X$ by a Laurent
        polynomial $p(X,X^{-1})$; nilpotency holds iff every irreducible factor
        of $X^n-1$ divides $p$.
  \item \textbf{Reducedness $\Leftrightarrow$ reversibility}: $X^n-1$ is
        separable iff $n$ is odd; relate to cycle structure and the factorization
        of $X^n-1$ into cyclotomic polynomials over $\FF_2$.
  \item \textbf{Higher characteristic}: over $\FF_p$ with rule $1+X$, nilpotency
        holds iff $n$ is a power of $p$; the proof skeleton generalizes directly.
  \item \textbf{Two dimensions}: extend to $\FF_2[X,Y]/(X^n-1,Y^m-1)$,
        connecting nilpotency to the geometry of $\mu_n \times \mu_m$.
\end{enumerate}

\section{Conclusion}

A childlike game on a necklace of black and white beads yields a sharp dichotomy
---mortality iff power-of-two length---which is one theorem written in four
alphabets: dynamics, algebra, geometry, and arithmetic. The automaton dies out
completely precisely when the roots-of-unity scheme $\mu_n$ over $\FF_2$
degenerates into a single non-reduced fat point, precisely when $n$ is a power of
the characteristic, and the relaxation time measures the length of that fat point.

\end{document}

