"""
Global Mortality Dichotomy Verifier
-----------------------------------
For each lattice size n, compares two independent computations:
  (a) the arithmetic test  n = 2^k  (n & (n-1) == 0), and
  (b) the algebraic test: nilpotency of u = 1 + X in R_n = F_2[X]/(X^n - 1),
      detected by searching for the least N with u^N = 0.
The main theorem asserts these always agree; the demo asserts it for all n<=32.
"""
from __future__ import annotations
from typing import Optional

def f2_mul(a: int, b: int) -> int:
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r

def f2_mod(a: int, m: int) -> int:
    dm = m.bit_length() - 1
    while a and a.bit_length() - 1 >= dm:
        a ^= m << ((a.bit_length() - 1) - dm)
    return a

def f2_mulmod(a: int, b: int, m: int) -> int:
    return f2_mod(f2_mul(a, b), m)

def is_power_of_two(n: int) -> bool:
    return n > 0 and (n & (n - 1)) == 0

def nilpotency_index(n: int) -> Optional[int]:
    m = (1 << n) | 1            # X^n - 1 = X^n + 1 over F_2
    u, power = 0b11, f2_mod(1, (1 << n) | 1)
    for N in range(1, 4 * n + 2):
        power = f2_mulmod(power, u, m)
        if power == 0:
            return N
    return None

if __name__ == "__main__":
    for n in range(1, 33):
        idx = nilpotency_index(n)
        assert (idx is not None) == is_power_of_two(n), n
        print(f"n={n:>2}  power_of_two={is_power_of_two(n)!s:>5}  "
              f"nilpotency_index={idx}")
    print("Verified: u nilpotent  <=>  n = 2^k  for all n <= 32.")

