function POWMOD(base, exp, m):
    result <- 1 mod m
    base   <- base mod m
    while exp > 0:
        if exp is odd:
            result <- (result * base) mod m      # carry-less mul, then reduce
        base <- (base * base) mod m
        exp  <- exp >> 1
    return result

