def f2_mul(a: int, b: int) -> int:
    """Carry-less multiplication of two F_2 polynomials (bitmask encoding)."""
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r

def f2_mod(a: int, m: int) -> int:
    """Reduce a modulo m in F_2[X]."""
    dm = m.bit_length() - 1
    while a and a.bit_length() - 1 >= dm:
        a ^= m << ((a.bit_length() - 1) - dm)
    return a

def f2_powmod(base: int, exp: int, m: int) -> int:
    """base**exp in F_2[X]/(m) via square-and-multiply; O(log exp) mulmods."""
    result = f2_mod(1, m)
    base = f2_mod(base, m)
    while exp:
        if exp & 1:
            result = f2_mod(f2_mul(result, base), m)
        base = f2_mod(f2_mul(base, base), m)
        exp >>= 1
    return result

