from typing import Set, Tuple, Optional

def ca_step(state: int, n: int) -> int:
    """One step on Z/n: multiply by (1 + X) = XOR with cyclic rotation."""
    rot = ((state << 1) | (state >> (n - 1))) & ((1 << n) - 1)
    return state ^ rot

def orbit_fate(state: int, n: int) -> Tuple[bool, int]:
    """Trace a single orbit; return (dies?, transient_or_period_length)."""
    seen: Set[int] = set()
    s, steps = state, 0
    while s not in seen:
        if s == 0:
            return True, steps
        seen.add(s)
        s = ca_step(s, n)
        steps += 1
    return False, steps

def global_nilpotency_census(n: int) -> bool:
    """True iff EVERY configuration on Z/n dies. Exhaustive, O(2^n * n)."""
    return all(orbit_fate(s, n)[0] for s in range(1 << n))
